  HOUSE_SPLIT, HOUSE_INNER_DOORS, HOUSE_WALL_FEATS, HOUSE_ATTACH, HOUSE_NEEDS, HOUSE_HEARTHS, HOUSE_DEPENDS,
  HOUSE_SATELLITES, HOUSE_HEARTH_FRONT, HOUSE_FOOTPRINTS, HOUSE_SPAN, HOUSE_OUTDOOR, HOUSE_INDOOR, HOUSE_HEARTH_GAP,
  HOUSE_ROOM_HEARTHS, HOUSE_UNIQUE, HOUSE_HEARTH_STYLES, HOUSE_SHIFTS, HOUSE_CONTOURS, HOUSE_CONTOUR_STEP, HOUSE_NEAR_KIND, HOUSE_WIDTHS,
