  7:  { name: 'Beige stone',        door: 60, win: 108,            doorSide: 1, decor: 'town' },
  10: { name: 'Seaside village',    door: 79, win: 161, back: 173, doorSide: 1, decor: 'cottage' },
  14: { name: 'Wood shack 1',       door: 10, win: 24,  back: 24,  doorSide: 1, decor: 'cottage' },
