    wit.rows = wit.grid.split('/').map(r => { const out = []; for (let i = 0; i < r.length; i += 3) { const t = r.slice(i, i + 3); out.push(t === 'xxx' ? null : parseInt(t, 16)); } return out; });
    wit.clsAt = new Map(wit.units.filter(u => u.wcls).map(u => [`${u.x + 1},${u.y + 1}`, u.wcls]));
    model.addWitness(wit.rows, (c, r) => wit.clsAt.get(`${c},${r}`) ?? null);
