// A unit's footprints: for its things on the floor, and for those hung on a wall, the offsets something else of that
// sort may stand at - those all its things of that sort allow (by "key:rotation", else by key; else, on the floor, those
// of its category). null: it has nothing of that sort. Hung things may hang above floor things.
const HUNG = new Set(HOUSE_FOOTPRINTS.hung.map(String));
// The roof the game's houses of a wall style have (the most common one), or null when it has none of that style.
export const roofForWallStyle = style => {
  const counts = HOUSE_STYLE_ROOFS[style];
  if (counts) return Number(Object.entries(counts).sort((a, b) => b[1] - a[1])[0][0]);
  // a style no shipped house has: one of the roofs the game uses, by style, so they do not all get the map's usual one
  if (style == null || !Number.isFinite(Number(style))) return null;
  const used = [...new Set(Object.values(HOUSE_STYLE_ROOFS).flatMap(c => Object.keys(c).map(Number)))].sort((a, b) => a - b);
  return used.length ? used[Number(style) % used.length] : null;
};
// Whether a roof (its number) can roof an L, T or U: those whose inner-corner pieces close corners in the game's houses.
// A house whose roof cannot stays a rectangle (its roof is never swapped for another: the roof goes with the walls).
export const roofTakesShapes = num => HOUSE_CONCAVE_ROOFS.includes(num);
const ZONE_OK =new Set(['plant', 'light', 'decal', 'wall decor']);   // what may stand before a house's door
