//   portals   [{ wx, wy, dir, door, num }]      (num is the portal.mes number; door false = a window)
//   scenery   [{ wx, wy, key, rot }]            (key is the scenery.mes number)
//   facades   [{ wx, wy, num, frame }]          facade cells stamped over the floor: the rugs (also as rugs [{ num, wx, wy, w, h }])
//   tiles     [[wx, wy], ...]                   the house's floor
