        let e = 0;
        WITNESSES.forEach((wit, i) => { e += weights[i] * wit.units.filter(u => (u.room >= 0) === isIn && u.wcls === c).length / wit.area; });
        const cap = WFC_ANCHORS.includes(c) ? seeds.filter(s => s === c).length : Math.max(2, Math.ceil(2 * e / sum0 * area));
