        const near = t => { const [x, y] = t.split(',').map(Number); let n = 0; for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) if ((dx || dy) && solved.has(tk(x + dx, y + dy))) n++; return n; };
